input.command:
ssh ha 'docker inspect -f "{{.State.Running}}" homeassistant; python3 -c "
import json;d=json.load(open(\"/config/.storage/core.config_entries\"))
for x in d[\"data\"][\"entries\"]:
    if x[\"domain\"]==\"lock_code_manager\": print(x[\"title\"], \"v\", x.get(\"version\"), x.get(\"minor_version\"), \"subentries:\", len(x.get(\"subentries\",[])))
"; docker logs --since 10m homeassistant 2>&1 | grep -E "\] \[custom_components\.lock_code_manager|lock_code_manager\] " | grep -iE "ERROR|WARNING" | grep -v "helpers.frame" | cut -c1-260 | tail -20' 2>&1 | grep -v "bashrc\|Warning: Perm"

